Suggested fix: move the guard inside the span (after tracer.Start), set the error status on the span, and then return — consistent with how other store functions handle pre-condition failures. Example:

  ctx, span := tracer.Start(ctx, "store.ListScheduled", ...)
  defer span.End()
  start := time.Now()
  defer func() {
      telemetry.RecordStoreOp(ctx, "ListScheduled", start, err)
      if err != nil {
          span.RecordError(err)
          span.SetStatus(codes.Error, err.Error())
      } else {
          span.SetAttributes(...)
      }
  }()
  if !state.valid() {
      err = fmt.Errorf("invalid scheduled state %q ...")
      return nil, err
  }

